  Lemma seg_rom_bss_ia : forall z, 0x12e9c0 <= z < 0x1af9f0 -> PropExec.seg_rom BSEGS2 (wa z) = Some (b8 0).
  Proof.
    intros z Hz. unfold PropExec.seg_rom, memory_read. rewrite wa_unsigned by lia. change (Z.of_N 1) with 1.
    replace (find_segment BSEGS2 z 1) with (Some AsanUbsan_segment_003).
    2:{ rewrite both_segs_eq. cbn -[Z.leb Z.add Z.of_N]. cbn [Z.of_N seg_base seg_size AsanUbsan_segment_000 AsanUbsan_segment_001 AsanUbsan_segment_002 AsanUbsan_segment_003].
        destruct (Z.leb_spec 65536 z); destruct (Z.leb_spec (z + 1) (65536 + 253952)); cbn [andb]; try lia;
        destruct (Z.leb_spec 319488 z); destruct (Z.leb_spec (z + 1) (319488 + 831488)); cbn [andb]; try lia;
        destruct (Z.leb_spec 1150976 z); destruct (Z.leb_spec (z + 1) (1150976 + 32768)); cbn [andb]; try lia;
        destruct (Z.leb_spec 1183744 z); destruct (Z.leb_spec (z + 1) (1183744 + 5648384)); cbn [andb]; try lia. reflexivity. }
    replace (seg_readable AsanUbsan_segment_003) with true by reflexivity.
    cbn [seg_bytes seg_base N.to_nat Pos.to_nat Pos.iter_op segment_read_bytes AsanUbsan_segment_003].
    change (Z.of_N 1425792%N) with 1183744.
    cbn [AsanUbsan_segment_003 seg_bytes]. change (N.to_nat 1) with 1%nat. cbn [segment_read_bytes].
    match goal with |- context [segment_byte_at ?l ?o] => replace (segment_byte_at l o) with (Some (b8 0)); [reflexivity|] end.
    symmetry. eapply (AsanHexTree.segment_byte_at_zero_pt _ _ _ _ ia_zero_scan); [rewrite both_len3; cbn; lia | lia].
  Qed.
